<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Hash,Storage,Crypt,Http,Event,Cache};
use Illuminate\Support\Str;
use App\Services\{Settings,Wallet,Identity,SafeZip,Updates,Backups,Notifications};
use App\Support\Json;
use Database\Seeders\DatabaseSeeder;
final class AdministrationTest extends TestCase {
    use RefreshDatabase;
    protected function setUp(): void {parent::setUp();$this->seed(DatabaseSeeder::class);Http::preventStrayRequests();Storage::fake('local');}
    private function admin(string $role='owner'): int {return DB::table('admins')->insertGetId(['name'=>'Test admin','email'=>Str::uuid().'@example.com','password'=>Hash::make('Strong-owner-password-9182'),'role'=>$role,'created_at'=>now(),'updated_at'=>now()]);}
    private function player(): array {return app(Identity::class)->guest(['device_name'=>'Test','platform'=>'android','device_id'=>(string)Str::uuid()]);}
    private function auth(array $p): array {return ['Authorization'=>'Bearer '.$p['access_token'],'Idempotency-Key'=>(string)Str::uuid()];}
    private function zip(array $files): string {$path=Storage::disk('local')->path(Str::uuid().'.zip');$zip=new \ZipArchive();$zip->open($path,\ZipArchive::CREATE);foreach($files as$name=>$body)$zip->addFromString($name,$body);$zip->close();return $path;}
    public function test_all_thirteen_admin_modules_and_eight_setting_views_render(): void {$id=$this->admin();$this->withSession(['admin_id'=>$id,'admin_reauth_at'=>time()]);for($module=1;$module<=13;$module++)$this->get('/admin/module/'.$module)->assertOk()->assertSee('PuzzleQuest');foreach(['general','android','ios','push','security','privacy','hosting','google']as$tab)$this->get('/admin/module/13?tab='.$tab)->assertOk();}
    public function test_admin_login_and_unauthorized_roles_are_enforced(): void {$id=$this->admin('content');$this->get('/admin')->assertRedirect('/admin/login');$this->post('/admin/login',['email'=>DB::table('admins')->where('id',$id)->value('email'),'password'=>'Strong-owner-password-9182'])->assertRedirect('/admin');$this->get('/admin/module/3')->assertOk();$this->get('/admin/module/11')->assertForbidden();$this->post('/admin/module/4',['action'=>'offer_price','id'=>'hint_pack','price'=>1])->assertForbidden();}
    public function test_expired_admin_reauthentication_prevents_sensitive_mutation(): void {$id=$this->admin();$this->withSession(['admin_id'=>$id,'admin_reauth_at'=>time()-700])->post('/admin/module/9',['action'=>'ad_units','units'=>'123'])->assertSessionHasErrors('reauth');$this->assertDatabaseMissing('settings',['key'=>'ad_units']);}
    public function test_secret_settings_are_encrypted_and_never_rendered(): void {$secret='never-render-this-real-looking-test-secret';app(Settings::class)->set('smtp',['host'=>'mail.example.com','password'=>$secret],true);$stored=DB::table('settings')->where('key','smtp')->value('value');$this->assertStringNotContainsString($secret,$stored);$this->assertSame($secret,app(Settings::class)->get('smtp')['password']);$this->withSession(['admin_id'=>$this->admin(),'admin_reauth_at'=>time()])->get('/admin/module/13')->assertOk()->assertDontSee($secret);}
    public function test_legal_pages_stay_unpublished_until_actual_approved_text_exists(): void {$this->get('/privacy')->assertStatus(503);$this->withSession(['admin_id'=>$this->admin(),'admin_reauth_at'=>time()])->post('/admin/module/13',['action'=>'settings','kind'=>'legal_gate','reviewed'=>1])->assertSessionHasErrors();$this->assertDatabaseMissing('settings',['key'=>'legal_approved']);}
    public function test_zip_slip_is_rejected_before_any_file_extraction(): void {$archive=$this->zip(['../escaped.txt'=>'not allowed']);$this->expectException(\RuntimeException::class);app(SafeZip::class)->extract($archive,Storage::disk('local')->path('stage'));}
    public function test_signed_release_is_verified_and_env_payload_is_rejected(): void {$pair=sodium_crypto_sign_keypair();$secret=sodium_crypto_sign_secretkey($pair);config(['puzzlequest.release_public_key'=>base64_encode(sodium_crypto_sign_publickey($pair))]);$php="<?php\nreturn true;\n";$manifest=Json::encode(['deployment_layout'=>'cpanel_fixed_subdomain_v1','version'=>'1.1.1','from_version'=>app(Updates::class)->version(),'php_min'=>'8.3.0','files'=>['app/UpdateProbe.php'=>hash('sha256',$php)]]);$archive=$this->zip(['release.json'=>$manifest,'release.sig'=>base64_encode(sodium_crypto_sign_detached($manifest,$secret)),'payload/app/UpdateProbe.php'=>$php]);$verified=app(Updates::class)->verify($archive);$this->assertSame('verified',$verified['state']);$bad=Json::encode(['version'=>'1.1.1','from_version'=>app(Updates::class)->version(),'php_min'=>'8.3.0','files'=>['.env'=>hash('sha256','not allowed')]]);$badArchive=$this->zip(['release.json'=>$bad,'release.sig'=>base64_encode(sodium_crypto_sign_detached($bad,$secret)),'payload/.env'=>'not allowed']);$this->expectException(\RuntimeException::class);app(Updates::class)->verify($badArchive);}
    public function test_encrypted_backup_roundtrip_and_tamper_rejection(): void {$in=Storage::disk('local')->path('plain.txt');$encrypted=Storage::disk('local')->path('backup.pqb');$out=Storage::disk('local')->path('restored.txt');file_put_contents($in,str_repeat('private sample data',80000));$backups=app(Backups::class);$backups->encrypt($in,$encrypted);$backups->decrypt($encrypted,$out);$this->assertSame(hash_file('sha256',$in),hash_file('sha256',$out));$bytes=file_get_contents($encrypted);$bytes[100]=chr(ord($bytes[100])^1);file_put_contents($encrypted,$bytes);$this->expectException(\RuntimeException::class);$backups->decrypt($encrypted,Storage::disk('local')->path('tampered.txt'));}
    public function test_read_all_never_marks_a_message_arriving_after_snapshot_even_same_second(): void {$p=$this->player();$service=app(Notifications::class);$uid=$p['player']['id'];$service->inbox($uid,'old','system',['ar'=>'قديم','en'=>'Old'],['ar'=>'رسالة','en'=>'Message'],['screen'=>'inbox']);$snapshot=$this->getJson('/api/v1/inbox',$this->auth($p))->assertOk()->json('read_all_snapshot_id');$service->inbox($uid,'new','system',['ar'=>'جديد','en'=>'New'],['ar'=>'رسالة','en'=>'Message'],['screen'=>'inbox']);$this->postJson('/api/v1/inbox/read-all',['snapshot_id'=>$snapshot],$this->auth($p))->assertOk()->assertJsonPath('marked_read',1);$this->assertNull(DB::table('inbox')->where('logical_id','new')->value('read_at'));}
    public function test_export_contains_no_passwords_tokens_or_otp(): void {$p=$this->player();DB::table('users')->where('id',$p['player']['id'])->update(['is_guest'=>false,'email'=>'export@example.com','email_verified_at'=>now()]);$id=(string)Str::uuid();DB::table('exports')->insert(['id'=>$id,'user_id'=>$p['player']['id'],'created_at'=>now(),'updated_at'=>now()]);(new \App\Jobs\BuildExport($id))->handle();$e=DB::table('exports')->where('id',$id)->first();$zip=new \ZipArchive();$zip->open(Storage::disk('local')->path($e->path));$json=$zip->getFromName('personal-data.json');$zip->close();$this->assertStringNotContainsString('password',$json);$this->assertStringNotContainsString($p['access_token'],$json);$this->assertStringNotContainsString('token_hash',$json);$other=$this->player();$this->getJson('/api/v1/account/exports/'.$id.'/download',$this->auth($other))->assertNotFound();}
    public function test_guest_merge_does_not_double_start_or_prior_level_grants(): void {$g=$this->player();$target=$this->player();$gid=$g['player']['id'];$uid=$target['player']['id'];DB::table('users')->where('id',$uid)->update(['is_guest'=>false,'email'=>'merge@example.com','email_verified_at'=>now()]);app(Wallet::class)->change($gid,'first:green_valley_house_001',['coins'=>500]);app(Wallet::class)->change($uid,'first:green_valley_house_001',['coins'=>500]);app(Wallet::class)->change($gid,'first:level_002_windmill_spring',['coins'=>500]);$merged=app(Identity::class)->merge($gid,$uid);$this->assertSame(1300,$merged['wallet']['coins']);$this->assertSame(2,$merged['wallet']['hints']);$this->getJson('/api/v1/me',$this->auth($g))->assertUnauthorized();}
    private function pushContext(?string $zone='UTC'): array {$p=$this->player();$uid=$p['player']['id'];DB::table('users')->where('id',$uid)->update(['is_guest'=>false,'email_verified_at'=>now(),'timezone'=>$zone,'preferences'=>Json::encode(['push'=>true])]);DB::table('push_devices')->insert(['id'=>(string)Str::uuid(),'user_id'=>$uid,'api_token_id'=>DB::table('api_tokens')->where('user_id',$uid)->value('id'),'token'=>Crypt::encryptString('fake-device-token'),'token_hash'=>hash('sha256',Str::uuid()),'platform'=>'android','permission'=>true,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);$cid=(string)Str::uuid();DB::table('push_campaigns')->insert(['id'=>$cid,'category'=>'system','title'=>'{"ar":"نظام","en":"System"}','body'=>'{"ar":"رسالة","en":"Message"}','target'=>'{"screen":"inbox"}','audience'=>'{}','state'=>'scheduled','expires_at'=>now()->addDay(),'created_at'=>now(),'updated_at'=>now()]);$did=(string)Str::uuid();DB::table('push_deliveries')->insert(['id'=>$did,'campaign_id'=>$cid,'user_id'=>$uid,'original_due_at'=>now()->subMinutes(10),'due_at'=>now(),'timezone'=>$zone,'created_at'=>now(),'updated_at'=>now()]);return [DB::table('push_deliveries')->where('id',$did)->first(),DB::table('push_campaigns')->where('id',$cid)->first(),DB::table('users')->find($uid)];}
    public function test_quiet_hours_defer_only_inside_six_hour_grace(): void {$this->travelTo(\Carbon\CarbonImmutable::parse('2026-11-25T12:00:00Z'));[$d,$c,$u]=$this->pushContext('America/New_York');[$action,$next]=app(Notifications::class)->decision($d,$c,$u);$this->assertSame('defer',$action);$this->assertSame('13:00',$next->format('H:i'));$this->travelTo(\Carbon\CarbonImmutable::parse('2026-11-26T04:00:00Z'));DB::table('push_campaigns')->where('id',$c->id)->update(['expires_at'=>now()->addDay()]);$d->original_due_at=now()->subMinutes(10);$c->expires_at=now()->addDay();[$action,$reason]=app(Notifications::class)->decision($d,$c,$u);$this->assertSame('suppress',$action);$this->assertSame('quiet_hours_outside_grace',$reason);}
    public function test_unknown_timezone_and_late_push_are_suppressed(): void {$this->travelTo(\Carbon\CarbonImmutable::parse('2026-11-25T12:00:00Z'));[$d,$c,$u]=$this->pushContext(null);$this->assertSame(['suppress','missing_timezone'],app(Notifications::class)->decision($d,$c,$u));$u->timezone='UTC';$d->original_due_at=now()->subHours(7);$this->assertSame(['suppress','late_more_than_six_hours'],app(Notifications::class)->decision($d,$c,$u));}
    public function test_rolling_24_hour_cap_is_not_a_calendar_day_reset(): void {$this->travelTo(\Carbon\CarbonImmutable::parse('2026-11-25T12:00:00Z'));[$d,$c,$u]=$this->pushContext();for($i=0;$i<2;$i++){$prior=(array)$c;$prior['id']=(string)Str::uuid();DB::table('push_campaigns')->insert($prior);DB::table('push_deliveries')->insert(['id'=>(string)Str::uuid(),'campaign_id'=>$prior['id'],'user_id'=>$u->id,'state'=>'sent_to_provider','attempted_at'=>now()->subHours(18+$i),'created_at'=>now(),'updated_at'=>now()]);}$this->assertSame(['suppress','rolling_24h_cap'],app(Notifications::class)->decision($d,$c,$u));}
    public function test_critical_security_exception_is_system_generated_and_still_permission_gated(): void {$this->travelTo(\Carbon\CarbonImmutable::parse('2026-11-25T02:00:00Z'));[$d,$c,$u]=$this->pushContext(null);$c->critical=true;$c->category='account_security';$this->assertSame(['send',null],app(Notifications::class)->decision($d,$c,$u));$u->preferences='{"push":false}';$this->assertSame(['suppress','preference_disabled'],app(Notifications::class)->decision($d,$c,$u));}
}
